<script setup lang="ts">
import VisionModelSettings from '../foundation/VisionModelSettings.vue'
import SceneModelSettings from '../world/SceneModelSettings.vue'
import {computed,ref,onMounted,onUnmounted,watch} from 'vue'
import {Plus,ArrowLeft,Check,Star} from 'lucide-vue-next'
import {api,newKey} from '../api'
import type {Profile,Plan,Task} from '../api/types'
import Sheet from '../components/Sheet.vue'
import {useApp} from '../stores/app'
import {mimoPreset} from '../api/profiles'
import {useRequestScope} from '../platform/request-scope'
import {watchTask,taskFinished} from '../api/task-watch'
const emit=defineEmits<{updated:[]}>()
const store=useApp(),profiles=ref<Profile[]>([]),usageRefresh=ref(0),hosts=ref<string[]>([]),adding=ref(false),editing=ref<Profile|null>(null),error=ref(''),busy=ref(false),name=ref(''),baseUrl=ref(''),modelId=ref(''),key=ref(''),windowSize=ref(32768),outputParameter=ref('max_tokens'),supportsJson=ref(false),callBudget=ref(100),inputBudget=ref(1000000),outputBudget=ref(100000),testProfile=ref<Profile|null>(null),plan=ref<Plan|null>(null),testResult=ref('')
const loading=ref(true)
const capture=useRequestScope();let loadGeneration=0,actionGeneration=0,testGeneration=0,stopTest:(()=>void)|undefined
const unlimitedCalls=computed({get:()=>callBudget.value===0,set:(value:boolean)=>{callBudget.value=value?0:100}})
const channel=ref<'mimo'|'custom'>('mimo'),advanced=ref(false);let panelEpoch=0
function chooseChannel(value:string){channel.value=value==='custom'?'custom':'mimo';advanced.value=channel.value==='custom';if(channel.value==='mimo'){name.value=mimoPreset.name;baseUrl.value=mimoPreset.baseUrl;modelId.value=mimoPreset.modelId;windowSize.value=mimoPreset.contextWindow;outputParameter.value=mimoPreset.outputParameter;supportsJson.value=mimoPreset.supportsJson}}
function closeProfile(){panelEpoch++;actionGeneration++;busy.value=false;adding.value=false;editing.value=null;key.value=''}
async function load(){const scope=capture(),generation=++loadGeneration,valid=()=>scope.valid()&&generation===loadGeneration;loading.value=true;error.value='';try{const data=await api<{items:Profile[];allowedHosts:string[]}>('/model-profiles');if(!valid())return;profiles.value=data.items.filter(p=>(p as Profile&{purpose?:string}).purpose!=='vision');hosts.value=data.allowedHosts;usageRefresh.value++;emit('updated')}catch(e){if(valid())error.value=(e as Error).message}finally{if(valid())loading.value=false}}
function addPreset(){panelEpoch++;adding.value=true;key.value='';chooseChannel('mimo')}
async function makeDefault(p:Profile){const scope=capture(),generation=++actionGeneration;busy.value=true;error.value='';try{await api('/model-profiles/'+p.id+'/default',{method:'PUT'});if(scope.valid()&&generation===actionGeneration){await load();if(scope.valid())store.message('默认模型已更新')}}catch(e){if(scope.valid()&&generation===actionGeneration)error.value=(e as Error).message}finally{if(scope.valid()&&generation===actionGeneration)busy.value=false}}
async function create(){const scope=capture(),generation=++actionGeneration,panel=panelEpoch,valid=()=>scope.valid()&&generation===actionGeneration&&panel===panelEpoch;busy.value=true;error.value='';try{await api('/model-profiles',{method:'POST',body:{name:name.value,baseUrl:baseUrl.value,modelId:modelId.value,key:key.value,contextWindow:windowSize.value,outputParameter:outputParameter.value,supportsJson:supportsJson.value,callBudget:callBudget.value,inputBudget:inputBudget.value,outputBudget:outputBudget.value}});if(!valid())return;key.value='';adding.value=false;await load()}catch(e){if(valid())error.value=(e as Error).message}finally{if(scope.valid()&&generation===actionGeneration)busy.value=false}}
function edit(p:Profile){panelEpoch++;advanced.value=false;editing.value=p;name.value=p.name;key.value='';callBudget.value=p.callBudget;inputBudget.value=p.inputBudget;outputBudget.value=p.outputBudget}
async function update(revoke=false){if(!editing.value)return;const scope=capture(),generation=++actionGeneration,panel=panelEpoch,profile={...editing.value},valid=()=>scope.valid()&&generation===actionGeneration&&panel===panelEpoch&&editing.value?.id===profile.id;busy.value=true;try{await api('/model-profiles/'+profile.id,{method:'PATCH',body:{expectedVersion:profile.version,name:name.value,...(key.value?{key:key.value}:{}),callBudget:callBudget.value,inputBudget:inputBudget.value,outputBudget:outputBudget.value,...(revoke?{status:'revoked'}:{})}});if(!valid())return;editing.value=null;key.value='';await load()}catch(e){if(valid())error.value=(e as Error).message}finally{if(scope.valid()&&generation===actionGeneration)busy.value=false}}
async function estimateTest(p:Profile){stopTest?.();testProfile.value=p;plan.value=null;testResult.value='';busy.value=false;const scope=capture(),generation=++testGeneration,valid=()=>scope.valid()&&generation===testGeneration&&testProfile.value?.id===p.id;try{const result=await api<Plan>('/operation-plans',{method:'POST',body:{operation:'connection_test',profileId:p.id}});if(valid())plan.value=result}catch(e){if(valid())error.value=(e as Error).message}}
async function runTest(){
  if(!testProfile.value||!plan.value||busy.value)return
  const scope=capture(),generation=++testGeneration,profileId=testProfile.value.id,confirmedPlan={...plan.value},requestKey=newKey(),valid=()=>scope.valid()&&generation===testGeneration&&testProfile.value?.id===profileId
  busy.value=true;error.value=''
  try{
    const consent=await api<{consentId:string}>('/consents',{method:'POST',body:{planId:confirmedPlan.planId,planHash:confirmedPlan.planHash,profileId,maxCalls:confirmedPlan.maxCalls,inputTokens:confirmedPlan.inputTokens,outputTokens:confirmedPlan.outputTokens}});if(!valid())return
    const task=await api<{taskId:string}>('/model-profiles/'+profileId+'/test',{method:'POST',key:requestKey,body:{operation:'connection_test',profileId,consentId:consent.consentId}});if(!valid())return
    plan.value=null;testResult.value='测试任务已保存，正在等待结果';stopTest?.()
    stopTest=watchTask(task.taskId,async(result:Task)=>{if(!valid())return;if(taskFinished(result)){testResult.value=result.state==='succeeded'?'连接测试结果已保存':'连接测试失败：'+(result.errorCode||result.state);busy.value=false;await load()}},e=>{if(valid())error.value=e.message})
  }catch(e){if(valid()){error.value=(e as Error).message;busy.value=false}}
}
watch(()=>testProfile.value?.id,()=>{++testGeneration;stopTest?.();busy.value=false},{flush:'sync'})
onUnmounted(()=>{++testGeneration;stopTest?.()})
onMounted(load)
</script>
<template><div class="model-advanced-settings"><div class="row between"><h2>个人模型通道（可选）</h2><button :disabled="!store.online" @click="addPreset"><Plus :size="18"/>添加通道</button></div><p class="hint">内测无需填写密钥；只有希望使用个人通道时，才需要调整以下设置。</p><p v-if="error" class="error" role="alert">{{error}}<button :disabled="loading" @click="load">重新加载</button></p><p v-if="loading" class="hint" role="status">正在加载模型通道…</p><div v-if="!loading&&!error&&!profiles.length" class="hint">平台模型暂未就绪，请联系管理员。阅读和已保存历史仍可使用。<br>管理员允许的主机：{{hosts.join('、')||'尚未配置可用通道'}}</div><article v-for="p in profiles" :key="p.id" class="list-item"><div class="row between"><div><h2>{{p.name}} <span v-if="p.isDefault" class="badge default-model"><Check :size="13"/>默认模型</span> <span class="badge">{{p.status==='active'?(p.hasKey===false?'待补充 Key':'可用配置'):'已撤销'}}</span></h2><details><summary>调用预算与通道信息</summary><p>{{p.modelId}} · {{p.source==='platform'?'平台提供，无需填写密钥':'Key 尾号 '+p.keyTail}}<br>{{p.callsReserved}} / {{p.unlimitedUsage||p.callBudget===0?'不限次数':p.callBudget}} 次调用预算已预留或使用</p><p v-if="p.source==='platform'" class="muted">平台通道预算由管理员维护。你也可以添加自己的通道并设为默认。</p><p class="muted"><small>输入 {{p.inputReserved}} / {{p.unlimitedUsage?'不限':p.inputBudget}}，输出 {{p.outputReserved}} / {{p.unlimitedUsage?'不限':p.outputBudget}} token；未知调用保留最坏情况预留。</small></p></details></div></div><div class="actions"><button v-if="!p.isDefault" :disabled="p.status!=='active'||p.hasKey===false||busy||!store.online" @click="makeDefault(p)"><Star :size="17"/>设为默认</button><button v-if="p.source!=='platform'" :disabled="p.status!=='active'" @click="edit(p)">管理预算与 Key</button><button :disabled="p.status!=='active'||p.hasKey===false||busy||!store.online" @click="estimateTest(p)">查看连接测试计划</button></div></article><details><summary>图像与画面校验设置</summary><p>默认出图通道已由平台准备；只有需要更换时才调整这些设置。</p><VisionModelSettings/><SceneModelSettings/></details><Sheet v-if="adding||editing" :title="editing?'管理通道':'添加模型通道'" @close="closeProfile"><form @submit.prevent="editing?update():create()"><fieldset :disabled="busy" style="border:0;margin:0;padding:0;min-width:0"><template v-if="!editing"><label>通道<select v-model="channel" @change="chooseChannel(channel)"><option value="mimo">OpenCode Go · MiMo</option><option value="custom">自定义兼容通道</option></select></label><label>模型标识<input v-model="modelId" required maxlength="100"></label></template><label>{{editing?'新 Key（留空保持）':'API Key'}}<input v-model="key" type="password" autocomplete="off" :required="!editing" maxlength="500"><small>只在提交时发送，不保存到客户端。</small></label><details :open="advanced" @toggle="advanced=($event.target as HTMLDetailsElement).open"><summary>高级设置与用量上限</summary><label>通道名称<input v-model="name" required maxlength="100"></label><template v-if="!editing"><label>兼容 Chat Completions 的基础地址<input v-model="baseUrl" required placeholder="https://允许的主机/v1"><small>允许主机：{{hosts.join('、')||'未配置'}}</small></label><label>声明的上下文窗口<input v-model.number="windowSize" type="number" min="4096" required></label><label>输出限额参数<select v-model="outputParameter"><option>max_tokens</option><option>max_completion_tokens</option></select></label><label class="row"><input v-model="supportsJson" type="checkbox" style="width:20px">请求 JSON 输出参数</label></template><label class="row"><input v-model="unlimitedCalls" type="checkbox" style="width:20px">不限调用次数</label><label v-if="!unlimitedCalls">调用总预算<input v-model.number="callBudget" type="number" min="1" required></label><label>输入 token 总上限<input v-model.number="inputBudget" type="number" min="1" required></label><label>总输出 token 上限（含模型思考与正文）<input v-model.number="outputBudget" type="number" min="1" required></label></details><p v-if="error" class="error">{{error}}</p><button class="primary" :disabled="busy">保存配置</button><button v-if="editing" type="button" class="danger" style="margin-left:8px" :disabled="busy" @click="update(true)">撤销 Key</button></fieldset></form></Sheet><Sheet v-if="testProfile" title="连接测试授权" @close="testProfile=null;plan=null"><p>连接测试可能收费，不会自动开始。</p><div v-if="plan" class="plan-box"><p>{{plan.providerName}} · {{plan.modelId}}</p><p>最多 {{plan.maxCalls}} 次调用，输入 {{plan.inputTokens}} / 总输出 {{plan.outputTokens}} token 上限。费用未知。</p><p v-if="plan.completionPolicy?.stages.connection_test?.thinking==='disabled'">连接探针不启用思考。</p><button class="primary" :disabled="busy" @click="runTest">确认预算并测试</button></div><p v-if="testResult" class="hint">{{testResult}}</p><p v-if="error" class="error">{{error}}</p></Sheet></div></template>
